head.script:
// 테스트 설명, 유효성 값 설정
//  ★ _3 : DrillDown 구성 전용 분리 샘플.
//     rowIndex 하위절 "DrillDown 으로 숨겨진 Row 는 인덱스에 포함되지 않습니다." 1건만 검증한다.
//     (기본 구성 / @description 하위절 / @param 본문 / colIndex / info / oldValue / newValue / @spec 2건 = _1 담당,
//      MultiLine 관련 = _2 담당 → 중복이므로 본 샘플에서 제외)
scwin.tData = {
    "description" : "[gridView > E > onyearselect]<br/>inputType='calendar' 인 Body Cell 의 팝업 달력에서 연도의 선택을 변경했을때 발생합니다.",
    "validation" : [
        "DrillDown 으로 숨겨진 Row 는 인덱스에 포함되지 않습니다."
    ]
}



// 같은 Row 에서 다시 연도를 변경했을 때 이전 rowIndex 와 나란히 비교하기 위한 이력
scwin.gVar = { "history" : {} };



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 검증 데이터 — DrillDown 계층 (depth 1=부모 / 2=자식)
//   DataList 인덱스 : 영업본부(0) > 영업1팀(1), 영업2팀(2) / 개발본부(3) > 개발1팀(4) / 관리팀(5)
//   cdate 는 달력 Column 과 바인딩되는 dataType="date" 컬럼이며 값은 순수 yyyyMMdd 문자열.
//   팝업 달력은 Cell 에 저장된 날짜의 연/월로 열리므로 개발본부(20260210) 는 항상 2026년 2월로 열린다.
//   → 연도 SelectBox 조작 시 oldValue 는 실행일과 무관하게 항상 2026 으로 고정된다.
scwin.TREE_DATA = [
    { "name": "영업본부", "cdate": "20260110", "depth": 1 },
    { "name": "영업1팀", "cdate": "20260120", "depth": 2 },
    { "name": "영업2팀", "cdate": "20260130", "depth": 2 },
    { "name": "개발본부", "cdate": "20260210", "depth": 1 },
    { "name": "개발1팀", "cdate": "20260220", "depth": 2 },
    { "name": "관리팀", "cdate": "20260310", "depth": 1 }
];



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - DrillDown 트리(inputType="drilldown" + depthColumn="depth") + 달력 Column 구성
//  - showDepth="2" → 최초엔 부모/자식 6 Row 가 모두 표시된 상태
//      표시0 영업본부 / 표시1 영업1팀 / 표시2 영업2팀 / 표시3 개발본부 / 표시4 개발1팀 / 표시5 관리팀
//  - 영업본부의 토글 아이콘을 클릭해 자식 2건(영업1팀/영업2팀)을 접으면
//      표시0 영업본부 / 표시1 개발본부 / 표시2 개발1팀 / 표시3 관리팀
//      → 개발본부 Row 의 달력 팝업에서 연도를 변경했을 때 rowIndex 가 3 에서 1 로 앞당겨진다.
//  - 달력 Column 은 inputType="calendar" + dataType="date" + viewType="icon" + calendarValueType="yearMonthDate"
//      (dataType 이 text 이면 표시값 뒤에 포맷 토큰이 리터럴로 붙음)
scwin.comp_init = async function () {
    // 기존 target / DataList 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }

    // 선택 이력 초기화
    scwin.gVar.history = {};

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    //  · createLabel 문자 제약 : 작은따옴표 금지, 줄바꿈은 개행문자 사용
    $c.gcm.createLabel('label="[전제] DrillDown 트리 그리드입니다. 최초에는 부모/자식 6 Row 가 모두 펼쳐진 상태이며 표시 순서는 영업본부(0) - 영업1팀(1) - 영업2팀(2) - 개발본부(3) - 개발1팀(4) - 관리팀(5) 입니다. 두번째 Column(일자) 이 달력 Cell 이며, 개발본부의 일자는 2026-02-10 이라 팝업 달력은 항상 2026년으로 열립니다.\n[절차] 1) 펼친 상태에서 개발본부 Row 의 일자 Cell 을 클릭해 입력창을 연 뒤 달력 아이콘을 눌러 팝업 달력을 열고, 상단 연도 SelectBox 에서 다른 연도(예: 2027년)를 선택한 뒤 팝업을 닫습니다. 2) 영업본부 이름 Cell 왼쪽의 토글 아이콘을 클릭해 자식 2건(영업1팀 / 영업2팀)을 접습니다. 3) 접힌 상태에서 다시 개발본부 Row 의 일자 Cell 에서 같은 방식으로 연도 SelectBox 를 조작합니다.\n[확인] 같은 Row 에서 다시 연도를 변경하면 이전 변경 시 rowIndex 와 현재 rowIndex 가 나란히 출력됩니다. 접은 뒤 개발본부의 rowIndex 는 3 에서 1 로 앞당겨집니다. 토글 아이콘을 다시 클릭해 펼치고 연도를 변경하면 3 으로 되돌아옵니다."', '', 'label1');

    // === 바인딩 DataList(dlt_bind) ===
    //  - depth : 계층 깊이(number). drilldown 컬럼의 depthColumn 으로 사용 (부모=1, 자식=2)
    //  - cdate : 달력 Column 바인딩 컬럼 → dataType="date" 필수
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cdate" name="cdate" dataType="date"></w2:column>';
    strDlt += '<w2:column id="depth" name="depth" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON(scwin.TREE_DATA, false);

    // target 그리드 구성 (rowNum 표시 → 화면에 보이는 Row 순번을 눈으로 확인 가능)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" rowNumVisible="true" rowNumHeaderValue="No." defaultCellHeight="30" ev:onyearselect="scwin.target1_onyearselect" id="" style="width:520px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="onyearselect DrillDown sample"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="280" style="" inputType="text" id="hcol_name" value="이름(DrillDown)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol_cdate" value="일자(달력)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="280" style="" inputType="drilldown" depthColumn="depth" showDepth="2" depthStartIndex="1" id="name" dataList="name"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="calendar" dataType="date" viewType="icon" calendarValueType="yearMonthDate" displayFormat="yyyy-MM-dd" id="cdate" dataList="cdate"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
};



// onyearselect : 팝업 달력 상단 SelectBox 로 연도를 변경했을 때 발생
//  - 본 샘플은 DrillDown 표시 기준 rowIndex 검증 전용이므로 rowIndex 를 중심으로 출력
//  - 선택된 Row 의 이름은 getRealRowIndex(표시 인덱스) → DataList 조회로 구해 함께 표시
//  - 같은 Row 에서 다시 연도를 변경하면 이전 rowIndex 와 현재 rowIndex 를 나란히 덧붙여 출력
scwin.target1_onyearselect = function (rowIndex, colIndex, info) {
    let bottom = wf_body_bottom.getObj("scwin");

    // 표시 인덱스 → DataList 인덱스로 변환하여 선택된 Row 의 이름을 구함
    let realIndex = target1.getRealRowIndex(rowIndex);
    let rowName = dlt_bind.getCellData(realIndex, "name");

    bottom.setReturnValue("▶ onyearselect (선택 Row : " + rowName + ", 연도 " + info.oldValue + " -> " + info.newValue + ")");
    bottom.setReturnValue("rowIndex : " + rowIndex);

    let prevIndex = scwin.gVar.history[rowName];
    if (prevIndex !== undefined) {
        bottom.setReturnValue("[" + rowName + "] 이전 변경 rowIndex : " + prevIndex + " / 현재 rowIndex : " + rowIndex);
    }
    scwin.gVar.history[rowName] = rowIndex;
};
